import os
import re
import zipfile
import xml.etree.ElementTree as ET

NS = {
    'm': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main',
    'r': 'http://schemas.openxmlformats.org/officeDocument/2006/relationships',
    'rel': 'http://schemas.openxmlformats.org/package/2006/relationships',
}

print("--- directory listing ---")
for f in sorted(os.listdir('.')):
    print(f, os.path.getsize(f) if os.path.isfile(f) else '(dir)')

path = 'budget.xlsx'
z = zipfile.ZipFile(path)
print("\n--- zip entries ---")
for n in z.namelist():
    print(n)

def col_to_idx(ref):
    m = re.match(r'([A-Z]+)(\d+)', ref)
    letters, row = m.group(1), int(m.group(2))
    idx = 0
    for ch in letters:
        idx = idx * 26 + (ord(ch) - ord('A') + 1)
    return idx, row

# workbook sheet list
wb = ET.fromstring(z.read('xl/workbook.xml'))
rels = ET.fromstring(z.read('xl/_rels/workbook.xml.rels'))
rid_to_target = {}
for rel in rels.findall('rel:Relationship', NS):
    rid_to_target[rel.get('Id')] = rel.get('Target')

sheets = []
for sh in wb.find('m:sheets', NS):
    sheets.append((sh.get('name'), rid_to_target.get(sh.get('{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id'))))

# shared strings
shared = []
if 'xl/sharedStrings.xml' in z.namelist():
    sst = ET.fromstring(z.read('xl/sharedStrings.xml'))
    for si in sst.findall('m:si', NS):
        text = ''.join(t.text or '' for t in si.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t'))
        shared.append(text)

for name, target in sheets:
    if target.startswith('/'):
        target = target[1:]
    else:
        target = 'xl/' + target
    print(f"\n=== Sheet: {name} (entry: {target}) ===")
    root = ET.fromstring(z.read(target))
    rows = []
    for row in root.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}row'):
        row_data = {}
        for c in row.findall('m:c', NS):
            ref = c.get('r')
            if ref is None:
                continue
            col, rnum = col_to_idx(ref)
            t = c.get('t')
            v = c.find('m:v', NS)
            val = None
            if t == 's' and v is not None:
                val = shared[int(v.text)]
            elif t == 'inlineStr':
                is_el = c.find('m:is', NS)
                if is_el is not None:
                    val = ''.join(tt.text or '' for tt in is_el.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t'))
            elif v is not None:
                val = v.text
                if t is None or t == 'n':
                    try:
                        val = float(val)
                    except ValueError:
                        pass
            row_data[col] = val
        if row_data:
            rows.append((rnum, row_data))
    for rnum, row_data in sorted(rows):
        for col in sorted(row_data):
            print(f"{rnum},{col}: {row_data[col]!r}")

